-- Replace the test agent's samples: the file behind the door item.
-- Generated by: python scripts/seed_agent_sample.py --door qa/servicing-seed/door-dry-run.sql. Do not edit by hand.
--
-- NOT RUN. No robot connects to Ohvara. The person with access runs this on live, only after Brayden says yes.
-- Test agent only (3f2b2df7-40b1-4921-80e2-09981c819642). Needs migrations 186 and 193 on live: section 3 stops by itself without them.
-- Run one section at a time: the Supabase SQL editor shows only the last result of what it runs.
-- Sections 1, 2 and 4 are one read-only statement each. Section 3 is one transaction.
-- BEFORE SECTION 3: replace every 00000000-0000-4000-8000-00000000f001 with the test fulfillment account id (section 1, row e).
-- Left as it is, section 3 stops at its first check and nothing changes.

-- ===== SECTION 1: read-only pre-check. These are the real live counts for the door item.
with p as (
  select pol.id, pol.status::text as status, pol.client_first_name, pol.client_last_name, pol.created_at,
         coalesce((to_jsonb(pol) ->> 'is_sample')::boolean, false) as flagged,
         md5(pol.agent_id::text || '|' || coalesce(nullif(right(regexp_replace(coalesce(pol.client_phone, ''), '\D', '', 'g'), 10), ''), pol.id::text)
             || '|' || lower(btrim(regexp_replace(coalesce(pol.client_first_name, '') || ' ' || coalesce(pol.client_last_name, ''), '\s+', ' ', 'g')))) as client_key
    from public.policies pol
   where pol.agent_id = '3f2b2df7-40b1-4921-80e2-09981c819642'
), flags(flagged) as (values (true), (false))
select 'a. all policies' as what, case when f.flagged then 'flagged' else 'unflagged' end as flag, '(all)' as status,
       count(p.id)::int as policies, count(distinct p.client_key)::int as clients, null::uuid as id, null::text as detail
  from flags f left join p on p.flagged = f.flagged
 group by f.flagged
union all
select 'b. by status', case when p.flagged then 'flagged' else 'unflagged' end, p.status,
       count(*)::int, count(distinct p.client_key)::int, null, null
  from p group by p.flagged, p.status
union all
select 'c. unflagged policy: survives the wipe, Brayden decides', 'unflagged', p.status, null, null, p.id,
       p.client_first_name || ' ' || p.client_last_name || ', created ' || p.created_at::date
  from p where not p.flagged
union all
select 'd. migrations', null, null, null, null, null,
       '186 is_sample: ' || (exists (select 1 from pg_attribute where attrelid = 'public.policies'::regclass and attname = 'is_sample' and not attisdropped))::text
       || ', 193 agent_clients: ' || (to_regclass('public.agent_clients') is not null)::text
union all
select 'e. active fulfillment account to pick from', case when pr.is_demo then 'demo side' else 'real side' end, null, null, null, pr.id, pr.full_name
  from public.profiles pr
 where pr.role::text = 'fulfillment' and pr.is_active
 order by 1, 2, 3, 7;

-- ===== SECTION 2: read-only list of live triggers and cron jobs. PGlite only replays migration files, so drift shows here.
with audited(name) as (select unnest(array['cron.daily-batch-assign', 'cron.eod-pipeline-sweep', 'cron.fulfillment-cancel-check', 'cron.fulfillment-pay-run', 'cron.missed-sweep', 'cron.notify-call-times', 'cron.notify-email', 'cron.notify-hourly', 'cron.notify-job-failures', 'cron.notify-lapse-checkins', 'cron.notify-push', 'cron.process-lead-queues', 'cron.process-reminders', 'cron.recovery-sms', 'cron.recovery-sweep', 'cron.redistribute-no-answers', 'cron.trigger-re-engagement', 'help_calls.help_calls_touch_updated_at', 'inbound_events.a0_block_inactive_writer', 'inbound_events.a0_block_locked_self_signup', 'lead_sms_replies.lead_sms_replies_e164', 'leads.a0_block_locked_self_signup', 'leads.lead_booked_assign_closer', 'leads.leads_agent_status_only', 'leads.leads_rep_outcome', 'leads.leads_typed_agents_only', 'leads.leads_typed_inbound_sync', 'leads.leads_updated_at', 'policies.a0_block_inactive_writer', 'policies.a0_block_locked_self_signup', 'policies.a0_block_self_signup_no_servicing', 'policies.a1_policies_demo', 'policies.a2_policies_servicing_guard', 'policies.audit_policies_delete', 'policies.policies_booking_rules', 'policies.policies_check_goal_milestones', 'policies.policies_compute_estimated_commission', 'policies.policies_enforce_weekly_cap', 'policies.policies_events_log', 'policies.policies_fulfillment_autoassign', 'policies.policies_fulfillment_cancel', 'policies.policies_missed_clear', 'policies.policies_notify', 'policies.policies_recompute_leaderboard', 'policies.policies_recovery_clear', 'policies.policies_reset_lapse_notified', 'policies.policies_sms_consent', 'policies.policies_stamp_cancellation_times', 'policies.policies_updated_at', 'policies.policies_zz_demo_guard', 'policy_events.policy_events_append_only', 'policy_events.policy_events_no_truncate', 'policy_fulfillment_details.a0_block_inactive_writer', 'policy_fulfillment_details.a0_block_locked_self_signup', 'policy_fulfillment_details.fulfillment_details_updated_at', 'policy_messages.a0_block_inactive_writer', 'policy_messages.a0_block_locked_self_signup', 'policy_messages.policy_messages_notify_trigger', 'policy_messages.policy_messages_stamp_trigger', 'servicing_tasks.a0_block_inactive_writer', 'servicing_tasks.a0_block_locked_self_signup', 'servicing_tasks.servicing_tasks_touch']))
select 'trigger' as kind, c.relname::text as on_table, t.tgname::text as name, t.tgenabled::text as enabled,
       pg_get_triggerdef(t.oid) as definition,
       case when exists (select 1 from audited a where a.name = c.relname || '.' || t.tgname) then 'in the audit'
            else 'NOT IN THE AUDIT: read it before running section 3' end as audit
  from pg_trigger t
  join pg_class c on c.oid = t.tgrelid
  join pg_namespace n on n.oid = c.relnamespace
 where n.nspname = 'public' and not t.tgisinternal and c.relname = any (array['policies', 'policy_fulfillment_details', 'policy_events', 'policy_messages', 'leads', 'lead_sms_replies', 'lead_followup_sms_log', 'inbound_events', 'servicing_tasks', 'help_calls'])
union all
select 'cron', null, j.jobname::text, j.active::text, j.command,
       case when exists (select 1 from audited a where a.name = 'cron.' || j.jobname) then 'in the audit'
            else 'NOT IN THE AUDIT: read it before running section 3' end
  from cron.job j
 order by 1, 2, 3;

-- ===== SECTION 3: the wipe and the seed, in one transaction.
-- Unflagged rows survive the wipe. The disable and enable lines for 3 triggers are in here, around the inserts.
-- Generated by scripts/seed_agent_sample.py. One transaction. Do not edit by hand.
-- Test agent only (3f2b2df7-40b1-4921-80e2-09981c819642); rows with an old policy held by fulfillment 00000000-0000-4000-8000-00000000f001.
begin;
set local ohvara.skip_assign_notify = 'on';
set local lock_timeout = '5s';

-- True when public.<t> exists and has an is_sample column.
create or replace function pg_temp.has_sample(t text) returns boolean
language sql stable as $$
  select exists (
    select 1 from pg_attribute
     where attrelid = to_regclass('public.' || t)
       and attname = 'is_sample' and not attisdropped)
$$;

-- Every policy date is counted back from this. It reads the clock when the SQL runs.
create or replace function pg_temp.wk_start() returns timestamptz language sql stable as $$
  select date_trunc('week', now())
$$;

-- No sample clients without the servicing tables and the test fulfillment account.
do $chk$
declare
  t text;
begin
  if to_regclass('public.agent_clients') is null then
    raise exception 'Sample seed stopped: agent_clients does not exist, so migration 193 is not applied. Nothing was seeded.';
  end if;
  foreach t in array array['policies', 'policy_fulfillment_details', 'policy_events', 'policy_messages', 'leads', 'servicing_tasks'] loop
    if not pg_temp.has_sample(t) then
      raise exception 'Sample seed stopped: public.% has no is_sample column, so a migration is missing. Nothing was seeded.', t;
    end if;
  end loop;
  if not exists (select 1 from public.profiles where id = '3f2b2df7-40b1-4921-80e2-09981c819642') then
    raise exception 'Sample seed stopped: the test agent profile does not exist.';
  end if;
  if not exists (select 1 from public.profiles
                  where id = '00000000-0000-4000-8000-00000000f001' and role::text = 'fulfillment' and coalesce(is_active, true)) then
    raise exception 'Sample seed stopped: fulfillment account 00000000-0000-4000-8000-00000000f001 does not exist or is not an active fulfillment account. Nothing was seeded.';
  end if;
  if (select coalesce(is_demo, false) from public.profiles where id = '00000000-0000-4000-8000-00000000f001')
     is distinct from (select coalesce(is_demo, false) from public.profiles where id = '3f2b2df7-40b1-4921-80e2-09981c819642') then
    raise exception 'Sample seed stopped: the fulfillment account and the test agent are on different demo sides.';
  end if;
end $chk$;

-- Wipe earlier sample rows first (same statements as wipe_agent_sample.py).
-- Wipe the test agent's sample rows only (is_sample and TEST_AGENT). Cascades take policy_events, policy_messages,
-- policy_fulfillment_details, lead_followup_sms_log, inbound_events and
-- servicing_tasks; none of them is deleted directly.
do $wipe$
declare
  v_ids text[] := '{}';
  n     integer;
begin
  -- 1. the test agent's sample policy ids
  if pg_temp.has_sample('policies') then
    select coalesce(array_agg(id::text), '{}') into v_ids from public.policies
       where is_sample and agent_id = '3f2b2df7-40b1-4921-80e2-09981c819642';
  end if;

  -- 2. bell rows and queued emails about those policies (keyed on the ids)
  if cardinality(v_ids) > 0 and to_regclass('public.notifications') is not null then
    if to_regclass('public.notification_emails') is not null then
      delete from public.notification_emails
       where notification_id in (select id from public.notifications
                                  where data->>'policy_id' = any (v_ids)
                                     or link = any (select '/messages?thread=' || x from unnest(v_ids) x));
      get diagnostics n = row_count; raise notice 'wipe notification_emails: %', n;
    end if;
    delete from public.notifications
     where data->>'policy_id' = any (v_ids)
        or link = any (select '/messages?thread=' || x from unnest(v_ids) x);
    get diagnostics n = row_count; raise notice 'wipe notifications: %', n;
  end if;

  -- 3. sample rows, children first where the link is ON DELETE SET NULL
  if pg_temp.has_sample('lead_sms_replies') then
    delete from public.lead_sms_replies
     where is_sample
       and lead_id in (select id from public.leads where is_sample and assigned_rep_id = '3f2b2df7-40b1-4921-80e2-09981c819642');
    get diagnostics n = row_count; raise notice 'wipe lead_sms_replies: %', n;
  else
    raise notice 'wipe skipped lead_sms_replies: no is_sample column';
  end if;

  if pg_temp.has_sample('help_calls') then
    delete from public.help_calls where is_sample and transfer_agent_id = '3f2b2df7-40b1-4921-80e2-09981c819642';
    get diagnostics n = row_count; raise notice 'wipe help_calls: %', n;
  else
    raise notice 'wipe skipped help_calls: no is_sample column';
  end if;

  if pg_temp.has_sample('leads') then
    delete from public.leads where is_sample and assigned_rep_id = '3f2b2df7-40b1-4921-80e2-09981c819642';
    get diagnostics n = row_count; raise notice 'wipe leads: %', n;
  else
    raise notice 'wipe skipped leads: no is_sample column';
  end if;

  if pg_temp.has_sample('policies') then
    delete from public.policies where is_sample and agent_id = '3f2b2df7-40b1-4921-80e2-09981c819642';
    get diagnostics n = row_count; raise notice 'wipe policies: % (one admin_audit_log row each, by design)', n;
  else
    raise notice 'wipe skipped policies: no is_sample column';
  end if;
end $wipe$;

