-- The flagged clients must read 2/7/2/1/1, or nothing above is kept.
do $stages$
declare
  v_read text;
begin
  select count(*) filter (where stage = 'setting_up') || '/' || count(*) filter (where stage = 'protected') || '/' || count(*) filter (where stage = 'needs_attention') || '/' || count(*) filter (where stage = 'ongoing') || '/' || count(*) filter (where stage = 'ended') from public.agent_clients where agent_id = '3f2b2df7-40b1-4921-80e2-09981c819642' and is_sample into v_read;
  if v_read is distinct from '2/7/2/1/1' then
    raise exception 'Sample seed stopped: the flagged clients read % (setting up/protected/needs attention/ongoing/ended), not 2/7/2/1/1. Nothing was seeded.', v_read;
  end if;
end $stages$;

alter table public.policies enable trigger policies_recompute_leaderboard;
alter table public.policies enable trigger policies_check_goal_milestones;
alter table public.policy_messages enable trigger policy_messages_notify_trigger;

-- Row counts per table (sample rows only).
do $sum$
declare
  t text;
  n bigint;
begin
  foreach t in array array['policies', 'policy_fulfillment_details', 'policy_events', 'policy_messages', 'leads', 'lead_sms_replies', 'lead_followup_sms_log', 'inbound_events', 'servicing_tasks', 'help_calls'] loop
    if pg_temp.has_sample(t) then
      execute format('select count(*) from public.%I where is_sample', t) into n;
      raise notice 'sample %: %', t, n;
    else
      raise notice 'skipped %: no is_sample column', t;
    end if;
  end loop;
end $sum$;

commit;

-- ===== SECTION 4: read-only post-seed check. The result column must start with PASS and read 2/7/2/1/1.
with counts as (
  select (select count(*) filter (where stage = 'setting_up') || '/' || count(*) filter (where stage = 'protected') || '/' || count(*) filter (where stage = 'needs_attention') || '/' || count(*) filter (where stage = 'ongoing') || '/' || count(*) filter (where stage = 'ended') from public.agent_clients where agent_id = '3f2b2df7-40b1-4921-80e2-09981c819642') as page_reads,
         (select count(*) filter (where stage = 'setting_up') || '/' || count(*) filter (where stage = 'protected') || '/' || count(*) filter (where stage = 'needs_attention') || '/' || count(*) filter (where stage = 'ongoing') || '/' || count(*) filter (where stage = 'ended') from public.agent_clients where agent_id = '3f2b2df7-40b1-4921-80e2-09981c819642' and is_sample) as samples_read,
         (select count(*) from public.policies where agent_id = '3f2b2df7-40b1-4921-80e2-09981c819642' and not is_sample) as unflagged_policies,
         (select count(*) from pg_trigger t join pg_class c on c.oid = t.tgrelid
           where not t.tgisinternal and t.tgenabled <> 'O' and c.relnamespace = 'public'::regnamespace
             and c.relname = any (array['policies', 'policy_messages'])) as triggers_off
)
select case
         when samples_read <> '2/7/2/1/1' then 'FAILED: the sample clients read ' || samples_read || ', not 2/7/2/1/1. Do not use these pages. Tell Brayden.'
         when triggers_off > 0 then 'FAILED: ' || triggers_off || ' trigger(s) are not enabled. Tell Brayden now.'
         when page_reads <> '2/7/2/1/1' then 'FAILED: the pages read ' || page_reads || ', not 2/7/2/1/1, because ' || unflagged_policies || ' unflagged policies survived the wipe. The samples alone read ' || samples_read || '.'
         else 'PASS: the pages read 2/7/2/1/1 (setting up/protected/needs attention/ongoing/ended).'
       end as result,
       page_reads, samples_read, unflagged_policies, triggers_off
  from counts;
